package com.example.project;

import android.app.ListActivity;import android.os.Bundle;import android.view.View;import android.widget.*;import java.util.*;
public class SampleListActivity extends ListActivity {ArrayList<CustomItem> items;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_list);items=new ArrayList<>(Arrays.asList(new CustomItem(R.drawable.apple,"Apple"),new CustomItem(R.drawable.pear,"Pear"),new CustomItem(R.drawable.banana,"Banana"),new CustomItem(R.drawable.strawberry,"Strawberry"),new CustomItem(R.drawable.pineapple,"Pineapple"),new CustomItem(R.drawable.mango,"Mango"),new CustomItem(R.drawable.cherry,"Cherry"),new CustomItem(R.drawable.persimmon,"Persimmon"),new CustomItem(R.drawable.melon,"Melon")));setListAdapter(new CustomAdapter1(this,items));findViewById(R.id.button2).setOnClickListener(v->finish());}@Override protected void onListItemClick(ListView list,View view,int position,long id){Toast.makeText(this,"Select Item = "+items.get(position).getName(),Toast.LENGTH_SHORT).show();}}
